import{_ as r,o as t,c as a,a5 as o}from"./chunks/framework.BmD0ICqc.js";const n="/study/images/graphics/gpu-resource-lifetime.svg",m=JSON.parse('{"title":"GPUが使うメモリはいつ再利用できるか — フェンスとリソースの寿命","description":"","frontmatter":{"title":"GPUが使うメモリはいつ再利用できるか — フェンスとリソースの寿命","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"アップロード領域をGPUに渡してからCPUが再利用するまでを図で追い、複数キューやPresentが絡むときの完了条件を区別する。","aliases":["GPUフェンス","GPU fence","アップロードヒープ","upload heap","ステージングバッファ","フレームスロット","リソースの寿命","遅延解放","deferred destruction"],"verification":"D3D12のキューとフェンス、Vulkanの同期仕様とPresent待ちセマフォ再利用の公式資料に照合（2026-11-06）"}},"headers":[],"relativePath":"graphics/optimization/gpu-resource-lifetime.md","filePath":"graphics/optimization/gpu-resource-lifetime.md"}'),i={name:"graphics/optimization/gpu-resource-lifetime.md"};function s(d,e,c,l,p,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="gpuが使うメモリはいつ再利用できるか-—-フェンスとリソースの寿命" tabindex="-1">GPUが使うメモリはいつ再利用できるか — フェンスとリソースの寿命 <a class="header-anchor" href="#gpuが使うメモリはいつ再利用できるか-—-フェンスとリソースの寿命" aria-label="Permalink to &quot;GPUが使うメモリはいつ再利用できるか — フェンスとリソースの寿命&quot;">​</a></h1><p>ゲームが頂点データをGPUに送るとき、CPUは先にコピー命令を提出し、次の仕事へ進めます。GPUが実際にコピー元を読むのはそのあとです。CPUが同じ領域に次の頂点を書いてしまうと、GPUが読む値まで変わり得ます。空き領域を<strong>確保する</strong>処理と、GPUが読み終わった領域を<strong>空きに戻す</strong>処理には、それぞれ別の条件があります。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/fence-based-resource-management" target="_blank" rel="noreferrer">Microsoftのフェンスによるリソース管理</a></p><h2 id="コピーの提出から、元の領域を空きに戻すまで" tabindex="-1">コピーの提出から、元の領域を空きに戻すまで <a class="header-anchor" href="#コピーの提出から、元の領域を空きに戻すまで" aria-label="Permalink to &quot;コピーの提出から、元の領域を空きに戻すまで&quot;">​</a></h2><p>Direct3D 12で、CPUが書けるアップロードバッファの領域Aから、GPUが描画で使う別のバッファへデータをコピーします。この例では、領域Aを読むコマンドを一つのキューにまとめます。</p><figure class="study-figure"><img src="'+n+'" alt="時間は左から右へ進む。CPUは領域Aに書き込み、GPUのコピーとフェンス値42の通知をキューに入れる。GPUがAを読んでコピーを終えるまで、CPUはAを保持する。CPUが完了値42を確認するとAを再利用できる。" width="760" height="322" loading="lazy"><figcaption>フェンス値42は、領域Aを最後に読むコピーより後ろにキューへ入れます。<a href="/study/images/graphics/gpu-resource-lifetime.svg" target="_blank" rel="noopener noreferrer">領域Aの寿命を拡大</a></figcaption></figure><ol><li><strong>CPUが書く。</strong> 空き範囲から領域Aを取り、CPUが頂点データを書きます。<code>CopyBufferRegion</code> を記録し、コピー元のバッファとオフセットを指定します。コピーが参照するのは、実行時にその範囲にあるデータです。</li><li><strong>コピーと完了の目印を提出する。</strong> コピーを含むコマンドリストを <code>ExecuteCommandLists</code> で提出し、同じ <code>ID3D12CommandQueue</code> に <code>Signal(fence, 42)</code> を続けて入れます。領域Aには、このキューのフェンスと値42を記録します。ここではキューごとに専用のフェンスを持ち、提出順に値を増やします。</li><li><strong>完了を確認して再利用する。</strong> <code>GetCompletedValue()</code> が正常に42以上を示したら、このコピーによる領域Aの使用は完了しています。ほかにAを使う予定がなければ、Aの範囲を空きに戻せます。領域Aを含むアップロードバッファ自体を解放するときは、その中のほかの範囲を使う命令も確認します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/uploading-resources" target="_blank" rel="noreferrer">コピー用データのアップロード</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12commandqueue-signal" target="_blank" rel="noreferrer">キューのSignal</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12fence-getcompletedvalue" target="_blank" rel="noreferrer">完了値の取得</a></li></ol><p>キューに入れた <code>ID3D12CommandQueue::Signal</code> は、GPUがその位置まで進んでからフェンス値を更新します。<code>ID3D12Fence::Signal</code> はCPUから値を直接更新するAPIなので、この完了の記録にはキュー側を使います。<code>GetCompletedValue()</code> がデバイス喪失時に返す <code>UINT64_MAX</code> は通常の完了と区別します。未完了で空き領域が必要になったら、別の空き範囲を使う、投入を後へ回す、<code>SetEventOnCompletion</code> で必要な値を待つといった扱いを選べます。リングバッファを使う場合も、折り返し先が未完了なら上書きできません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12fence-signal" target="_blank" rel="noreferrer">CPU側のSignal</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12fence-seteventoncompletion" target="_blank" rel="noreferrer">SetEventOnCompletion</a></p><h2 id="何を使い終えたかを分ける" tabindex="-1">何を使い終えたかを分ける <a class="header-anchor" href="#何を使い終えたかを分ける" aria-label="Permalink to &quot;何を使い終えたかを分ける&quot;">​</a></h2><table tabindex="0"><thead><tr><th>対象</th><th>確認する条件</th></tr></thead><tbody><tr><td>コピー元のアップロード領域</td><td>その範囲からの最後の読み出しが完了した。別のバッファへのコピーだけに使うなら、コピー完了で回収できる</td></tr><tr><td>コピー先のバッファ</td><td>コピーと、その結果を読む描画や計算がすべて完了した。後で使う予定もなくなれば解放できる</td></tr><tr><td>コマンドアロケータ</td><td>そのアロケータに記録されたコマンドのGPU実行がすべて終わった。フレームごとに枠を持つ場合は、枠に完了値を記録して次の <code>Reset</code> に使う</td></tr></tbody></table><p>リソースを論理的に手放す時点と、物理的な解放を分ける設計を<strong>遅延解放</strong>と呼びます。例えばシーンから消したメッシュは以後の描画に使わず、すでに提出した描画が終わるまで、バッファ本体とそれを参照する記述子を保持します。シェーダー可視の記述子スロットを使い回すときは、実行中の参照に加え、ルートシグネチャの静的記述子が記録時から要求する寿命にも従います。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12commandallocator-reset" target="_blank" rel="noreferrer">コマンドアロケータのReset</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/root-signature-version-1-1" target="_blank" rel="noreferrer">D3D12の静的記述子と揮発性記述子</a> · <a href="/study/game/asset-loading.html">アセットロードと所有権</a></p><h2 id="フェンス、バリア、presentで確認するもの" tabindex="-1">フェンス、バリア、Presentで確認するもの <a class="header-anchor" href="#フェンス、バリア、presentで確認するもの" aria-label="Permalink to &quot;フェンス、バリア、Presentで確認するもの&quot;">​</a></h2><p><strong>フェンス</strong>を使ってCPUが確認するのは、対象のキューがどこまで進んだかです。<strong>バリア</strong>はGPUのコマンド間に必要な順序やメモリアクセスの依存関係を指定します。例えばコピー先を次に描画で読むときは、D3D12のリソース状態やVulkanのステージ、アクセス、画像レイアウトに合わせて依存関係を指定します。GPUにバリアを記録した時点では、CPUがコピー元を再利用できるかは別途確認が必要です。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/using-resource-barriers-to-synchronize-resource-states-in-direct3d-12" target="_blank" rel="noreferrer">D3D12のリソースバリア</a> · <a href="https://docs.vulkan.org/spec/latest/chapters/synchronization.html" target="_blank" rel="noreferrer">Vulkanの同期仕様</a></p><p><strong>Present</strong>で渡した画像や待ちセマフォには、表示側での使用期間もあります。Vulkanでは描画を提出した <code>vkQueueSubmit</code> のフェンスで描画完了を確認できても、表示エンジンが <code>vkQueuePresentKHR</code> の待ちセマフォを使い終わったかは、そのフェンスだけでは分かりません。画像ごとにセマフォを持ち、同じ画像を再取得して取得の同期を待つ方法など、提示側まで含む条件で再利用します。<a href="https://docs.vulkan.org/guide/latest/swapchain_semaphore_reuse.html" target="_blank" rel="noreferrer">KhronosのPresent待ちセマフォ再利用ガイド</a> · <a href="/study/graphics/optimization/swap-chain-and-vsync.html">スワップチェーンとVSync</a></p><h2 id="複数キューにまたがるときは最後の参照を追う" tabindex="-1">複数キューにまたがるときは最後の参照を追う <a class="header-anchor" href="#複数キューにまたがるときは最後の参照を追う" aria-label="Permalink to &quot;複数キューにまたがるときは最後の参照を追う&quot;">​</a></h2><p>コピーキューから描画キューに頂点バッファを渡す場合、D3D12ではコピーキューの完了値を描画キューの <code>Wait</code> に指定し、そのあとで描画を実行できます。<code>Wait</code> は描画キューに待ちを入れるAPIで、呼び出したCPUスレッドはその場でブロックされません。コピー元をコピーキューだけが読むなら、その完了で元の範囲を回収できます。コピー先を解放するなら、描画キューでの最後の読み出しまで追います。独立した複数のキューが同じリソースを読む場合は、すべての完了値を確認するか、各キューの完了を待つキューでまとめて完了を記録します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/executing-and-synchronizing-command-lists" target="_blank" rel="noreferrer">D3D12のキュー間同期</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12commandqueue-wait" target="_blank" rel="noreferrer">キューのWait</a></p><p>Vulkanでは、キュー間の依存関係にセマフォを使います。異なるキューファミリー間で排他共有リソースを引き渡す場合、所有権の移譲が必要な条件では、渡す側のリリースと受け取る側のアクワイアも指定し、セマフォなどでその順序を保証します。CPU側の回収は、対象範囲を使ったすべてのキューについて完了を確認してから行います。<a href="https://docs.vulkan.org/guide/latest/synchronization_examples.html" target="_blank" rel="noreferrer">Vulkanの同期と所有権移譲の例</a></p><p>関連項目は、キューの進行を使って結果を読み戻す<a href="/study/graphics/optimization/gpu-timestamp-queries.html">GPUタイムスタンプクエリ</a>と、D3D12での記録・提出を扱う<a href="/study/graphics/api/directx12.html">DirectX 12</a>です。</p><p>D3D12のコマンドを複数スレッドで記録する場合は、記録中にどのスレッドがアロケーターを使うかと、GPUがその記録を使い終える時点の両方を管理します。<a href="/study/graphics/optimization/parallel-command-recording.html">D3D12の並列コマンド記録</a></p>',18)])])}const f=r(i,[["render",s]]);export{m as __pageData,f as default};
